public static void main(String[] args) {
	FastScanner sc = new FastScanner();
	int n = Integer.parseInt(sc.next());
	int m = Integer.parseInt(sc.next());
	int k = Integer.parseInt(sc.next());
	List<Test> tests = new ArrayList<>();
	for (int i = 0; i < m; i++) {
		int C = Integer.parseInt(sc.next());
		int keys = 0;
		for (int j = 0; j < C; j++) {
			int A = Integer.parseInt(sc.next());
			keys |= 1 << (A - 1);
		}
		char r = sc.next().charAt(0);
		tests.add(new Test(keys, r));
	}
	System.out.println(countValidCombinations(n, k, tests));
}

static class Test {
	int keys;
	char result;

	Test(int keys, char result) {
		this.keys = keys;
		this.result = result;
	}
}

static int countValidCombinations(int n, int k, List<Test> tests) {
	int validCount = 0;
	for (int combination = 0; combination < (1 << n); combination++) {
		if (isValidCombination(combination, n, k, tests)) {
			validCount++;
		}
	}
	return validCount;
}

static boolean isValidCombination(int combination, int n, int k, List<Test> tests) {
	for (Test test : tests) {
		int realKeyCount = Integer.bitCount(combination & test.keys);
		if ((test.result == 'o' && realKeyCount < k) || (test.result == 'x' && realKeyCount >= k)) {
			return false;
		}
	}
	return true;
}

